/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Mul, Pow, Sym, SymFunction, add, derivative, eulerEquations, fn, mul, pow, rational, symbols } from '../../src';
import { at, sympyStr } from '../sympy-str';

describe("doctests of sympy.calculus.euler", () => {
  it("euler_equations(L, x(t), t)", () => {
    const t = new Sym('t');
    expect(sympyStr([at(eulerEquations(add(mul(rational(1, 2), pow(derivative((SymFunction('x'))(t), [[t, 1]]), 2)), mul(rational(-1, 2), pow((SymFunction('x'))(t), 2))), [(SymFunction('x'))(t)], [t]), 0)])).toBe('[Eq(-x(t) - Derivative(x(t), (t, 2)), 0)]');
  });
  it("euler_equations(L, u(t, x), [t, x])", () => {
    const [t, x] = symbols('t x');
    expect(sympyStr([at(eulerEquations(add(mul(rational(1, 2), pow(derivative((SymFunction('u'))(t, x), [[t, 1]]), 2)), mul(rational(-1, 2), pow(derivative((SymFunction('u'))(t, x), [[x, 1]]), 2))), [(SymFunction('u'))(t, x)], [t, x]), 0)])).toBe('[Eq(-Derivative(u(t, x), (t, 2)) + Derivative(u(t, x), (x, 2)), 0)]');
  });
});

